HW.add({ders:"turkce", sinif:3, uniteler:[
  {ad:"Dinleme ve Konuşma", konular:[
    {id:"tr3-dinleme-konusma", ad:"Dinleme, İzleme ve Konuşma", e:"🎧",
     anlat:[
      {b:"Dinleme amacı", m:"Dinlerken amacımızı belirleriz: bilgi almak, öğrenmek ya da eğlenmek. Amaca göre dikkatimizi ayarlarız."},
      {b:"Konuyu bulma", m:"Dinlediğimiz metnin konusunu, kişilerini ve olaylarını belirleriz. Önemli bilgileri kısa notlarla yazarız."},
      {b:"Kontrol soruları", m:"Ne, nerede, ne zaman, kim, neden, nasıl sorularıyla dinlediğimizi kontrol ederiz.", o:"Ne zaman gittiler? Dün."},
      {b:"Hazırlıklı konuşma", m:"Konuşmadan önce ne söyleyeceğimizi düşünürüz. Giriş, gelişme, sonuç sırasıyla anlatırız. Ses tonumuzu ayarlarız."}
     ],
     ipucu:"Amacı belirle, notları al, soruyla kontrol et, sırayla anlat!",
     kartlar:[["Dinleme amacı ne olabilir?","Bilgi almak, öğrenmek"],["Dinlerken neyi belirleriz?","Konu, kişi, olay"],["Dinlediğimizi neyle kontrol ederiz?","5N1K soruları"],["Konuşma hangi sırayla yapılır?","Giriş, gelişme, sonuç"],["Konuşurken neyi ayarlarız?","Ses tonunu ve vurguyu"],["Anlamadığımızı ne yaparız?","Nazikçe sorarız"]],
     sorular:[
      {s:"Hangisi dinleme amacı olabilir?", c:["Bilgi edinmek","Gürültü yapmak","Konuyu bozmak"], a:"Dinlerken öğrenmek amaçlanır."},
      {s:"Dinlediğimizi kontrol etmek için hangi soruları kullanırız?", c:["Ne, nerede, ne zaman, kim, neden, nasıl","Yalnızca kaç","Yalnızca hangi renk"], a:"5N1K soruları metni kontrol eder."},
      {s:"Konuşmada hangi sıra doğrudur?", c:["Giriş, gelişme, sonuç","Sonuç, giriş, gelişme","Gelişme, sonuç, giriş"], a:"Konuşma giriş, gelişme, sonuç şeklinde ilerler."},
      {s:"Bir metni dinlerken önce neyi bulmaya çalışırız?", c:["Konuyu ve ana olayı","Cümle sayısını","Sayfa numarasını"], a:"Önce konuyu anlarız."},
      {s:"Hazırlıklı konuşmanın ilk adımı nedir?", c:["Ne söyleyeceğimizi düşünmek","Sessiz kalmak","Çok hızlı konuşmak"], a:"Önce düşünür, sonra konuşuruz."},
      {s:"Konuşurken ses tonu ne işe yarar?", c:["Duyguyu ve vurguyu anlatır","Dinleyiciyi susturur","Sözcükleri siler"], a:"Ses tonu anlamı güçlendirir."},
      {s:"Not alırken neye dikkat ederiz?", c:["Önemli kelimeleri yazarız","Her sözcüğü yazarız","Hiç yazmayız"], a:"Önemli kelimeler yeterlidir."},
      {s:"Olayın nerede geçtiğini bulmak için hangi soruyu sorarız?", c:["Nerede?","Kaç?","Kim?"], a:"Yer için nerede sorulur."},
      {s:"Bir arkadaşımız sunum yaparken ne yapmalıyız?", c:["Sessizce dinleyip sonunda soru sormalıyız","Konuşmaya başlamalıyız","Sınıftan çıkmalıyız"], a:"Saygılı dinleyici sonunda soru sorar."},
      {s:"'Dün ormanda yürüyüşe çıktık.' cümlesinde 'Ne zaman?' sorusunun cevabı nedir?", c:["Dün","Ormanda","Yürüyüş"], a:"Zaman bildiren sözcük dün'dür."}
     ]}
  ]},
  {ad:"Sözcükte Anlam", konular:[
    {id:"tr3-sozluk-alfabe", ad:"Sözlük ve Alfabetik Sıra", e:"📖",
     anlat:[
      {b:"Alfabetik sıra", m:"Sözcükler alfabedeki sıraya göre dizilir. İlk harfler aynıysa ikinci harfe bakılır.", o:"ağaç, anne, arı"},
      {b:"Sözlük kullanma", m:"Sözlükte sözcüğün ilk, ikinci, üçüncü harfine bakarak ilerleriz. Sayfa başındaki rehber sözcükler aradığımızı bulmamıza yardım eder."},
      {b:"Sözlük bilgisi", m:"Sözlük sözcüğün anlamını, türünü ve örnek cümlesini verir. Sözcüğün birden çok anlamı varsa anlamlar numaralanır.", o:"yüz: 1. Sayı. 2. Çehre."},
      {b:"Ansiklopedi", m:"Ansiklopedi, bir konu hakkında ayrıntılı bilgi veren kaynaktır. O da alfabe sırasına göre düzenlenir."}
     ],
     ipucu:"Alfabe sırasını bil, harf harf ilerle: sözlük seni bulur!",
     kartlar:[["Sözlükte sıralama nasıl?","Alfabe sırasına göre"],["Sayfa başındaki ve sonundaki sözcük","Rehber sözcük"],["Sözlük bize ne verir?","Sözcüğün anlamını"],["Ayrıntılı bilgi veren kaynak","Ansiklopedi"],["Hangisi önce gelir: ağaç, arı?","ağaç"],["Çok anlamlı sözcük sözlükte nasıl gösterilir?","Anlamlar numaralanır"]],
     sorular:[
      {s:"Hangi sıralama alfabe sırasına uygundur?", c:["ağaç, anne, arı","arı, ağaç, anne","anne, arı, ağaç"], a:"Alfabe sırası: ğ, n, r."},
      {s:"'çiçek', 'balık', 'elma' sözcüklerinden hangisi sözlükte önce gelir?", c:["balık","çiçek","elma"], a:"B, Ç ve E'den önce gelir."},
      {s:"'okul' ve 'oyun' sözcüklerinden hangisi sözlükte önce gelir?", c:["okul","oyun","ikisi birlikte"], a:"İkinci harfler k ve y: k önce gelir."},
      {s:"Sayfa başındaki ve sonundaki sözcüğü gösteren sözcüklere ne denir?", c:["Rehber sözcük","Madde başı","Ek"], a:"Bunlar rehber sözcüktür."},
      {s:"Hangi dizilim alfabe sırasına uygundur?", c:["elma, erik, incir","incir, elma, erik","erik, incir, elma"], a:"e-l, e-r, i sırasıyla."},
      {s:"Bir konu hakkında ayrıntılı bilgiyi hangi kaynaktan buluruz?", c:["Ansiklopedi","Takvim","Karne"], a:"Ansiklopedi ayrıntılı bilgi verir."},
      {s:"Sözlükte çok anlamlı sözcüğün anlamları nasıl gösterilir?", c:["Numaralanarak","Silinerek","Karıştırılarak"], a:"Her anlam bir numara alır."},
      {s:"Hangi sözcük sözlükte en sonda yer alır? gül, göl, gün, güneş", c:["güneş","gün","gül"], a:"Sıra: göl, gül, gün, güneş."},
      {s:"'sınıf' sözcüğünü sözlükte ararken önce hangi harfe bakarız?", c:["s","ı","f"], a:"Önce ilk harf: s."},
      {s:"Bir sözcüğün anlamını öğrenmek için hangisine bakarız?", c:["Sözlük","Atlas","Resim defteri"], a:"Anlam sözlükte bulunur."}
     ]},
{id:"tr3-es-zit-anlam", ad:"Eş ve Zıt Anlamlı Kelimeler", e:"↔️",
 anlat:[
  {b:"Eş anlamlı kelimeler", m:"Yazılışları farklı, anlamları aynı ya da çok yakın olan kelimelere eş anlamlı kelimeler denir. Aynı şeyi anlatmak için farklı kelimeler kullanabiliriz.", o:"güzel - hoş, çabuk - hızlı, kolay - basit"},
  {b:"Zıt anlamlı kelimeler", m:"Anlamları birbirinin tersi olan kelimelere zıt (karşıt) anlamlı kelimeler denir.", o:"sıcak - soğuk, uzun - kısa, açık - kapalı"},
  {b:"Metinde nasıl kullanırız?", m:"Eş anlamlı kelimeler aynı sözcüğü tekrar tekrar yazmaktan kurtarır, anlatımı zenginleştirir. Zıt anlamlılar ise iki şeyi karşılaştırırken işimize yarar.", o:"Hava sabah soğuktu, öğleden sonra sıcak oldu."},
  {b:"Dikkat!", m:"Her kelimenin eş ya da zıt anlamlısı olmayabilir. Ayrıca bir kelime cümledeki kullanımına göre farklı zıt anlamlara sahip olabilir.", o:"ağır çanta - hafif çanta"}
 ],
 ipucu:"Eş = aynı gibi (yan yana duran ikizler); Zıt = tersi (kuzey-güney, karşı karşıya duran kutuplar).",
 kartlar:[["güzel (eş anlamlı)","hoş"],["çabuk (eş anlamlı)","hızlı"],["ak (zıt anlamlı)","kara"],["uzun (zıt anlamlı)","kısa"],["cesur (eş anlamlı)","yürekli"],["dolu (zıt anlamlı)","boş"],["sabah (zıt anlamlı)","akşam"],["Eş anlamlı ne demek?","Anlamı aynı olan kelimeler"]],
 sorular:[
  {s:"Aşağıdakilerden hangisi 'kolay' kelimesinin eş anlamlısıdır?", c:["basit","zor","uzun","hızlı"], a:"Kolay ile basit aynı anlamdadır."},
  {s:"'Büyük' kelimesinin zıt anlamlısı hangisidir?", c:["küçük","iri","kocaman","koca"], a:"İri, kocaman ve koca büyük ile aynı anlamdadır; zıttı küçüktür."},
  {s:"'Çabuk' kelimesinin eş anlamlısı hangisidir?", c:["hızlı","yavaş","ağır","geç"], a:"Çabuk ile hızlı eş anlamlıdır."},
  {s:"Hangi çift zıt anlamlıdır?", c:["sıcak - soğuk","yol - cadde","ev - konut","hızlı - çabuk"], a:"Sıcak ile soğuk anlamca birbirinin tersidir."},
  {s:"Hangi çift eş anlamlıdır?", c:["okul - mektep","ak - kara","tatlı - ekşi","yaz - kış"], a:"Okul ile mektep aynı anlama gelir."},
  {s:"'Sabah' kelimesinin zıt anlamlısı hangisidir?", c:["akşam","sabahleyin","erken","gün"], a:"Sabahın zıddı akşamdır."},
  {s:"'Cesur' kelimesine en yakın anlamlı kelime hangisidir?", c:["yürekli","korkak","tembel","sessiz"], a:"Cesur ile yürekli eş anlamlıdır."},
  {s:"'Ayşe sınıfın en çalışkan öğrencisidir.' cümlesindeki 'çalışkan' sözcüğünün zıt anlamlısı hangisidir?", c:["tembel","gayretli","azimli","düzenli"], a:"Çalışkanın zıttı tembeldir."},
  {s:"Hangi sözcük grubunda her çiftin anlamı birbirinin zıttıdır?", c:["ince - kalın, uzun - kısa","kitap - kalem, defter - silgi","yol - cadde, ev - konut","dağ - tepe, deniz - göl"], a:"İnce-kalın ve uzun-kısa zıt anlamlı çiftlerdir."},
  {s:"'Güzel' sözcüğünün eş anlamlısı ile zıt anlamlısı sırasıyla hangi seçenekte doğru verilmiştir?", c:["hoş - çirkin","çirkin - hoş","hoş - iyi","kötü - çirkin"], a:"Güzel ile hoş eş anlamlı, güzel ile çirkin zıt anlamlıdır."}
 ]},
{id:"tr3-es-sesli", ad:"Eş Sesli Kelimeler", e:"🔊",
 anlat:[
  {b:"Eş sesli kelime nedir?", m:"Yazılışı ve okunuşu aynı, ama anlamları farklı olan kelimelere eş sesli (sesteş) kelimeler denir.", o:"yüz: 100 sayısı, surat, yüzmek"},
  {b:"Örnekler", m:"Çay hem içtiğimiz sıcak içeceğin hem de küçük akarsuyun adıdır. Ay hem gökteki gök cismidir hem de bir yılın 12 bölümünden biridir.", o:"çay, ay, gül, at, yaz, el, kır"},
  {b:"Anlamı cümle belirler", m:"Eş sesli bir kelimenin hangi anlamda kullanıldığını cümleden anlarız. Cümlenin geri kalanı bize ipucu verir.", o:"Yaz geldi. / Mektup yaz."},
  {b:"Eş sesli ile eş anlamlı karışmasın", m:"Eş anlamlıda yazılış farklı, anlam aynıdır. Eş seslide yazılış aynı, anlam farklıdır.", o:"güzel-hoş (eş anlamlı), at (hayvan) - at (fırlat) (eş sesli)"}
 ],
 ipucu:"Eş sesli: Sesi ikiz, anlamı ayrı! Aynı ses, farklı iş: yüz (sayı), yüz (yüzmek).",
 kartlar:[["Eş sesli kelime nedir?","Yazılışı aynı, anlamı farklı kelime"],["yüz kelimesinin anlamlarından biri","Yüzmek"],["çay: iki anlamı","İçecek ve akarsu"],["ay: iki anlamı","Gök cismi ve takvim ayı"],["gül: iki anlamı","Çiçek ve gülmek"],["yaz: iki anlamı","Mevsim ve yazmak"],["at: iki anlamı","Hayvan ve fırlatmak"],["Anlamı neye göre buluruz?","Cümledeki kullanıma göre"]],
 sorular:[
  {s:"Aşağıdakilerden hangisi eş sesli bir kelimedir?", c:["yüz","masa","kalem","okul"], a:"Yüz: sayı, surat ve yüzmek anlamlarına gelir."},
  {s:"'Bahçede açan gül çok güzel kokuyor.' cümlesindeki 'gül' kelimesi hangi anlamdadır?", c:["Çiçek","Gülmek eylemi","Sevinç","Renk"], a:"Cümlede bahçede açan bir çiçek anlatılıyor."},
  {s:"'Babam bana yeni bir at aldı.' cümlesinde 'at' kelimesi neyi anlatır?", c:["Hayvanı","Fırlatmayı","Bir yemeği","Bir oyuncağı"], a:"Alınan bir at, yani hayvandır."},
  {s:"'Top uzağa at.' cümlesinde 'at' sözcüğü hangi anlamdadır?", c:["Fırlatmak","Hayvan","Yarış","Koşu"], a:"Cümlede top fırlatılmasından söz ediliyor."},
  {s:"Hangi cümlede 'yaz' kelimesi mevsim anlamında kullanılmıştır?", c:["Yaz tatilinde denize gideceğiz.","Defterine adını yaz.","Tahtaya cevabı yaz.","Mektubu hemen yaz."], a:"Yaz tatili, mevsim olan yazdır."},
  {s:"'Çay' kelimesinin hem içecek hem akarsu anlamı olması onu hangi tür kelime yapar?", c:["Eş sesli","Eş anlamlı","Zıt anlamlı","Mecaz anlamlı"], a:"Yazılışı aynı, anlamları farklı kelimeler eş seslidir."},
  {s:"Hangi cümlede 'ay' kelimesi takvim bölümü anlamındadır?", c:["Bir ay sonra yaz tatiline gireceğiz.","Gece gökyüzünde ay parlıyordu.","Ay dede nasıl da yuvarlak!","Astronotlar ay yüzeyine indi."], a:"Bir ay sonra ifadesindeki ay, zaman birimidir."},
  {s:"Hangisi eş sesli kelime örneği DEĞİLDİR?", c:["güzel - hoş","kır - kır","el - el","yüz - yüz"], a:"Güzel-hoş eş anlamlıdır. Diğerleri aynı yazılan, farklı anlamlı kelimelerdir."},
  {s:"'Ben bu kitabı okudum. Yüzümdeki ben ise doğuştan.' cümlelerindeki iki 'ben' kelimesi için hangisi doğrudur?", c:["Biri zamir, biri vücuttaki leke anlamlıdır.","İkisi de aynı anlamdadır.","İkisi de zıt anlamlıdır.","İkisi de eş anlamlıdır."], a:"İlk ben kişiyi, ikinci ben ciltteki lekeyi anlatır; eş sesli kelimedir."},
  {s:"'Yüzümü yıkadım. Havuzda yüz metre yüzdüm.' cümlelerinde 'yüz' sözcüğü hangi iki anlamda kullanılmıştır?", c:["Surat ve sayı","Sayı ve yüzmek","Surat ve yüzmek","Sayı ve yer"], a:"İlkinde surat, ikincisinde 100 sayısı anlamındadır."}
 ]},
{id:"tr3-gercek-mecaz", ad:"Gerçek ve Mecaz Anlam", e:"💭",
 anlat:[
  {b:"Gerçek anlam", m:"Bir kelimenin ilk akla gelen, sözlükteki asıl anlamına gerçek anlam denir. Gerçek anlamda kelime olduğu gibi anlaşılır.", o:"Buz gibi soğuk su içtim. (gerçekten soğuk)"},
  {b:"Mecaz anlam", m:"Bir kelimenin asıl anlamından uzaklaşıp başka bir anlamda kullanılmasına mecaz anlam denir. Mecaz anlamda gerçekte olmayan bir benzetme vardır.", o:"Buz gibi bir insan. (soğuk, ilgisiz biri)"},
  {b:"Nasıl ayırt ederiz?", m:"Cümleyi gerçekten olabiliyor mu diye düşün. Tatlı bir elma gerçektir ama tatlı bir bebek tatlı sözcüğünün mecaz kullanımıdır.", o:"Tatlı dilli bir arkadaş."},
  {b:"Sık kullanılan mecazlar", m:"Sıcak karşılamak, kalbi kırılmak, ağır söz, yumuşak kalpli, sert konuşmak gibi ifadelerde kelimeler mecaz anlam taşır.", o:"Beni sıcak bir gülümsemeyle karşıladı."}
 ],
 ipucu:"Gerçek: eline alırsın, görürsün. Mecaz: hissedersin, benzetirsin. 'Sıcak çay' gerçek, 'sıcak ilgi' mecaz.",
 kartlar:[["Gerçek anlam nedir?","Kelimenin asıl anlamı"],["Mecaz anlam nedir?","Kelimenin başka bir anlamda kullanılması"],["'Soğuk su' hangi anlam?","Gerçek (su gerçekten soğuk)"],["'Soğuk insan' hangi anlam?","Mecaz (ilgisiz insan)"],["'Tatlı dilli' hangi anlam?","Mecaz (hoş konuşan)"],["'Ağır çanta' hangi anlam?","Gerçek (çantanın ağırlığı)"],["'Kalbi kırıldı' hangi anlam?","Mecaz (üzüldü)"],["'Sıcak çorba' hangi anlam?","Gerçek (çorba ısınmış)"]],
 sorular:[
  {s:"Hangi cümlede 'sıcak' kelimesi gerçek anlamda kullanılmıştır?", c:["Sıcak çorbayı üfleyerek içti.","Bizi sıcak bir sohbetle karşıladı.","Sıcak bir ses duyuldu.","Sıcak bir ilgi gördü."], a:"Çorbanın gerçekten sıcak olması gerçek anlamdır."},
  {s:"'Kırık bir kalple eve döndü.' cümlesindeki 'kırık' kelimesi hangi anlamdadır?", c:["Mecaz","Gerçek","Eş sesli","Zıt"], a:"Kalp gerçekten kırılmaz, üzgün olduğunu anlatır."},
  {s:"Hangi cümlede mecaz anlam vardır?", c:["Öğretmenimiz çok tatlı bir insan.","Tatlı kek çok güzeldi.","Dondurma tatlıydı.","Meyve suyu çok tatlı."], a:"İnsan için tatlı demek sevimli demektir, mecazdır."},
  {s:"'Ağır çanta omzumu ezdi.' cümlesindeki 'ağır' hangi anlamdadır?", c:["Gerçek","Mecaz","Zıt","Eş anlamlı"], a:"Çantanın gerçekten ağırlığı olduğu söylenmektedir."},
  {s:"'Beni sıcak karşıladı.' cümlesinde 'sıcak' ne anlama gelir?", c:["Samimi, içten","Yanıcı","Pişmiş","Isıtılmış"], a:"Sıcak karşılamak, içten ve güler yüzlü karşılamaktır."},
  {s:"'Sert' kelimesi hangi cümlede mecaz anlamdadır?", c:["Sert sözleriyle herkesi üzdü.","Sert bir taş buldum.","Sert ekmek yedim.","Kapı sert kapandı."], a:"Sözlerin sert olması kırıcı olmasını anlatır, mecazdır."},
  {s:"'Demir gibi bir irade' ifadesinde 'demir' ne anlatır?", c:["Çok güçlü olmayı","Metal bir eşya","Kapıyı","Pas tutmayı"], a:"Burada demir, güçlü anlamında mecaz olarak kullanılmıştır."},
  {s:"'Yumuşak' kelimesi hangi cümlede gerçek anlamlıdır?", c:["Yastık çok yumuşaktı.","Yumuşak huylu bir çocuktu.","Yumuşak bir sesle konuştu.","Yumuşak kalpli biriydi."], a:"Yastığın dokunuşla yumuşak olması gerçek anlamdır."},
  {s:"'Annem bugün biraz soğuk davrandı.' cümlesi için hangisi doğrudur?", c:["'Soğuk' mecaz anlamda, ilgisiz anlamında kullanılmıştır.","'Soğuk' gerçek anlamda kullanılmıştır.","Annemin elleri üşümüştür.","Hava soğuk olduğu için annem çok giyinmiştir."], a:"Davranışın soğuk olması ilgisizliği anlatır; mecazdır."},
  {s:"Hangi iki cümlede 'taş' kelimesi sırayla gerçek ve mecaz anlamda kullanılmıştır?", c:["Yoldan bir taş aldım. / Taş gibi bir kalbi vardı.","Taş gibi bir kalbi vardı. / Yoldan bir taş aldım.","Taş duvar yıkıldı. / Taş merdiven çıktım.","Taş gibi sağlam. / Taş gibi sert."], a:"Önce gerçek taş, sonra duygusuzluğu anlatan mecaz kullanım gelir."}
 ]},
    {id:"tr3-deyim-atasozu", ad:"Deyim ve Atasözü", e:"💬",
     anlat:[
      {b:"Deyim nedir?", m:"Deyim, kalıplaşmış ve çoğunlukla gerçek anlamından ayrı bir anlam taşıyan sözdür. Öğüt vermez.", o:"ağzı kulaklarına varmak = çok sevinmek"},
      {b:"Atasözü nedir?", m:"Atasözü, uzun yılların deneyimiyle oluşmuş, öğüt veren kalıplaşmış sözdür.", o:"Damlaya damlaya göl olur."},
      {b:"Aradaki fark", m:"Deyim bir durumu anlatır, öğüt vermez. Atasözü öğüt verir ve genel doğruyu anlatır."},
      {b:"Yerinde kullanma", m:"Deyim ve atasözlerini yerinde kullanırsak anlatımımız güzelleşir.", o:"Sınavı geçince ağzı kulaklarına vardı."}
     ],
     ipucu:"Deyim: söz kalıbı, öğüt yok. Atasözü: ders var, öğüt var!",
     kartlar:[["ağzı kulaklarına varmak","Çok sevinmek"],["burnu havada olmak","Kibirli olmak"],["kulak vermek","Dikkatle dinlemek"],["Damlaya damlaya göl olur","Az birikerek çok olur"],["Bir elin nesi var, iki elin sesi var","Birlik gücü artırır"],["Sakla samanı gelir zamanı","Biriktirmek ileride yarar"],["Öğüt veren söz","Atasözü"]],
     sorular:[
      {s:"'Ağzı kulaklarına varmak' deyimi ne anlatır?", c:["Çok sevinmek","Çok üzülmek","Çok konuşmak"], a:"Çok sevinen kişi için kullanılır."},
      {s:"'Damlaya damlaya göl olur.' atasözü hangi öğüdü verir?", c:["Az az biriktirirsek çok olur","Göllere gitmeliyiz","Yağmur çok yağar"], a:"Küçük birikimler büyür."},
      {s:"Hangisi bir atasözüdür?", c:["Sakla samanı, gelir zamanı.","Burnu havada olmak","Ağzı kulaklarına varmak"], a:"Öğüt veren kalıp söz atasözüdür."},
      {s:"Hangisi bir deyimdir?", c:["Burnu havada olmak","Bir elin nesi var, iki elin sesi var.","Ağaç yaşken eğilir."], a:"Burnu havada olmak öğüt vermeyen bir deyimdir."},
      {s:"'Bir elin nesi var, iki elin sesi var.' atasözü neyi anlatır?", c:["Birlikte çalışmanın gücünü","Elin ağrısını","Müzik yapmayı"], a:"Birlik beraberlik önemlidir."},
      {s:"'Kulak vermek' ne demektir?", c:["Dikkatle dinlemek","Kulağı kesmek","Gürültü yapmak"], a:"Kulak vermek dikkatle dinlemektir."},
      {s:"Deyimle atasözünü ayıran özellik hangisidir?", c:["Atasözü öğüt verir, deyim vermez","Deyim öğüt verir, atasözü vermez","İkisi de aynı anlamdadır"], a:"Atasözü öğüt verir."},
      {s:"'Ağaç yaşken eğilir.' atasözünün anlamı nedir?", c:["Eğitim küçük yaşta daha kolaydır","Ağaçlar eğilir","Yağmur ağacı kırar"], a:"Çocuk yaşta edinilen alışkanlıklar kolay yerleşir."},
      {s:"'Sınavdan yüksek not alınca ağzı kulaklarına vardı.' cümlesinde kişi nasıl hissetmiştir?", c:["Çok sevinmiştir","Çok kızmıştır","Yorulmuştur"], a:"Ağzı kulaklarına varmak çok sevinmektir."},
      {s:"Parasını biriktiren Zeynep'in davranışını hangi atasözü destekler?", c:["Sakla samanı gelir zamanı","Ağaç yaşken eğilir","Bir elin nesi var, iki elin sesi var"], a:"Biriktirmek ileride işe yarar."}
     ]}
  ]},
  {ad:"Kelime Türleri ve Ekler", konular:[
{id:"tr3-adlar", ad:"Adlar (İsimler)", e:"🏷️",
 anlat:[
  {b:"Ad (isim) nedir?", m:"Varlıklara, kişilere, yerlere ve kavramlara verilen sözcüklere ad (isim) denir. Etrafında gördüğün her şeyin bir adı vardır.", o:"kedi, masa, İzmir, Elif, sevgi"},
  {b:"Özel ad ve cins ad", m:"Tek bir varlığa verilen ada özel ad denir; büyük harfle başlar. Aynı türden varlıkların ortak adına cins ad denir; küçük harfle yazılır.", o:"Özel: Pamuk, Ankara. Cins: kedi, şehir."},
  {b:"Tekil, çoğul, topluluk adı", m:"Tek bir varlığı gösteren ad tekildir. -lar/-ler ekiyle çoğul olur. Topluluk adları ise tek sözcükle birden fazla varlığı anlatır; çoğul eki almasalar da çok varlık bildirir.", o:"kitap, kitaplar, sürü, orman, ordu"},
  {b:"Topluluk adlarına örnekler", m:"Sürü, orman, ordu, takım, sınıf, ekip, koro, kervan, filo birer topluluk adıdır. Sürü dediğimizde bir kişi değil, çok sayıda hayvan düşünürüz.", o:"koyun sürüsü, balık sürüsü, futbol takımı"}
 ],
 ipucu:"Özel ad = Özel isim, ID kartı gibi tektir, BÜYÜK harfle başlar. Cins ad = aynı türün hepsi.",
 kartlar:[["Özel ad örneği","Ankara"],["Cins ad örneği","şehir"],["Topluluk adı örneği","sürü"],["Çoğul eki","-lar / -ler"],["Özel adlar nasıl yazılır?","Büyük harfle başlar"],["'ağaç' tekil mi çoğul mu?","Tekil"],["'çiçekler' tekil mi çoğul mu?","Çoğul"],["Topluluk adı ne demek?","Tek sözcükle çok varlık bildiren ad"]],
 sorular:[
  {s:"Aşağıdakilerden hangisi özel addır?", c:["Pamuk","kedi","kitap","çocuk"], a:"Pamuk burada bir kedinin özel adıdır; tek bir varlığa verilmiştir."},
  {s:"Hangisi cins addır?", c:["öğretmen","Elif","Ege","Hacettepe"], a:"Öğretmen, aynı mesleği yapan herkesin ortak adıdır."},
  {s:"Hangisi çoğul bir addır?", c:["kalemler","kalem","sınıf","ağaç"], a:"Kalemler kelimesindeki -ler eki çoğul yapar."},
  {s:"Aşağıdakilerden hangisi topluluk adıdır?", c:["orman","ağaç","kuş","yaprak"], a:"Orman, çok sayıda ağacı bir arada anlatır."},
  {s:"'Çobanın koyun sürüsü dağa çıktı.' cümlesindeki topluluk adı hangisidir?", c:["sürü","çoban","koyun","dağ"], a:"Sürü, çok sayıda koyunu anlatan topluluk adıdır."},
  {s:"Hangi sözcük çoğul eki almıştır?", c:["çiçekler","çiçek","bahçe","gül"], a:"Çiçekler sözcüğü -ler eki almıştır."},
  {s:"Hangi cümlede yalnızca özel adlar vardır?", c:["Ali ile Ayşe İzmir'e gitti.","Çocuklar şehre gitti.","Öğrenciler okula geldi.","Kediler bahçede oynadı."], a:"Ali, Ayşe ve İzmir özel addır."},
  {s:"Hangi sözcük topluluk adı DEĞİLDİR?", c:["bayrak","ordu","takım","kervan"], a:"Bayrak tek bir nesnedir; diğerleri çok kişiden ya da varlıktan oluşur."},
  {s:"'Kızılay' ve 'Pamuk' sözcükleri için hangisi doğrudur?", c:["Her ikisi de özel addır.","Her ikisi de cins addır.","Biri topluluk adıdır.","Her ikisi çoğuldur."], a:"Tek bir kuruma ve tek bir varlığa verilen adlar özel addır."},
  {s:"'Öğrenciler bahçede futbol takımı kurdu.' cümlesinde kaç tane çoğul eki almış ad ve kaç tane topluluk adı vardır?", c:["Bir çoğul, bir topluluk","İki çoğul, bir topluluk","Bir çoğul, iki topluluk","Hiç çoğul, bir topluluk"], a:"Öğrenciler çoğuldur; takım topluluk adıdır."}
 ]},
{id:"tr3-sifat-eylem", ad:"Sıfat ve Eylem", e:"🏃",
 anlat:[
  {b:"Sıfat nedir?", m:"Adların önüne gelip onları özelliğiyle anlatan sözcüklere sıfat denir. Nasıl? sorusuna cevap verir.", o:"kırmızı elma, uzun yol, güzel çiçek"},
  {b:"Sıfatı nasıl buluruz?", m:"Önce adı bul, sonra o adın nasıl olduğunu sor. Sıfat, adın hemen önünde yer alır.", o:"Büyük bir köpek havladı. (Nasıl köpek? büyük)"},
  {b:"Eylem (fiil) nedir?", m:"İş, oluş ve hareket bildiren sözcüklere eylem (fiil) denir. Cümlede ne yapıldığını gösterir. Çoğunlukla -mak/-mek ile biter.", o:"yazmak, koşmak, solmak, gülmek"},
  {b:"İş, oluş, hareket", m:"İş bildirenler bir şey yapmayı, hareket bildirenler yer değiştirmeyi, oluş bildirenler kendiliğinden olan değişimi anlatır.", o:"yazdı (iş), koştu (hareket), soldu (oluş)"}
 ],
 ipucu:"Sıfat 'nasıl?' diye sorar ve adın önünde durur. Eylem 'ne yapıyor?' sorusunun cevabıdır.",
 kartlar:[["Sıfat ne işe yarar?","Adın özelliğini bildirir"],["Sıfat hangi soruya cevap verir?","Nasıl?"],["'mavi gökyüzü' sıfatı","mavi"],["Eylem ne bildirir?","İş, oluş, hareket"],["'koşmak' hangi eylem?","Hareket bildiren"],["'solmak' hangi eylem?","Oluş bildiren"],["'yazmak' hangi eylem?","İş bildiren"],["Sıfat nerede durur?","Adın önünde"]],
 sorular:[
  {s:"'Kırmızı elmayı yedim.' cümlesindeki sıfat hangisidir?", c:["kırmızı","elma","yedim","ben"], a:"Kırmızı, elmanın nasıl olduğunu söyler."},
  {s:"Aşağıdakilerden hangisi eylemdir?", c:["koşmak","masa","güzel","okul"], a:"Koşmak, hareket bildiren bir eylemdir."},
  {s:"'Uzun yolculuk çok yordu.' cümlesinde 'uzun' sözcüğü hangi görevdedir?", c:["Sıfat","Eylem","Özel ad","Çoğul ad"], a:"Uzun, yolculuğun özelliğini bildirir."},
  {s:"Hangi sözcük oluş bildiren eylemdir?", c:["solmak","yazmak","koşmak","atmak"], a:"Çiçek kendiliğinden solar; bu bir oluştur."},
  {s:"'Çocuk topu attı.' cümlesindeki eylem hangisidir?", c:["attı","çocuk","topu","atı"], a:"Cümlede yapılan iş 'attı' sözcüğüyle anlatılır."},
  {s:"Hangi sözcük grubunda yalnızca sıfatlar vardır?", c:["güzel, temiz, büyük","koşmak, gülmek, yazmak","masa, kalem, defter","Ali, Ayşe, Ankara"], a:"Güzel, temiz, büyük adların özelliğini bildirir."},
  {s:"'Yeşil yapraklar rüzgârda sallandı.' cümlesinde kaç sıfat ve kaç eylem vardır?", c:["Bir sıfat, bir eylem","İki sıfat, bir eylem","Bir sıfat, iki eylem","İki sıfat, iki eylem"], a:"Yeşil sıfat; sallandı eylemdir."},
  {s:"Hangisi hareket bildiren bir eylemdir?", c:["yürümek","solmak","kızarmak","büyümek"], a:"Yürümek, yer değiştirmeyi anlatır; diğerleri oluş bildirir."},
  {s:"'Sarı kediyi sevdim.' cümlesinde altı çizili olmasa da sıfat olan sözcük için hangisi doğrudur?", c:["Sarı, kediyi niteler.","Sevdim, kediyi niteler.","Kediyi, nitelik bildirir.","Bu cümlede sıfat yoktur."], a:"Sarı, kedinin rengini yani özelliğini söyler."},
  {s:"Aşağıdakilerden hangisinde hem sıfat hem eylem vardır?", c:["Kocaman kuş uçtu.","Bahçede çiçekler.","Mavi deniz.","Güzel hava."], a:"Kocaman sıfattır; uçtu eylemdir."}
 ]},
{id:"tr3-ekler", ad:"Ekler ve Çoğul Eki", e:"➕",
 anlat:[
  {b:"Kök ve ek", m:"Sözcüğün anlamlı ve bölünemeyen kısmına kök denir. Köke eklenen parçalar ekdir. Ekler sözcüğün anlamını ya da görevini değiştirir.", o:"göz + lük = gözlük"},
  {b:"Çoğul eki: -lar / -ler", m:"Çoğul eki varlığın birden fazla olduğunu gösterir. Kalın ünlülerden sonra -lar, ince ünlülerden sonra -ler gelir.", o:"kitap-lar, ev-ler, kuş-lar, göz-ler"},
  {b:"Hal ekleri (sezdirme)", m:"Adlara gelen bazı ekler, adı cümledeki diğer kelimelere bağlar. -i: neyi? (kitabı), -e: nereye? (okula), -de: nerede? (evde), -den: nereden? (evden).", o:"okula gitti, evde kaldı, bahçeden geldi"},
  {b:"Yapım eki", m:"Yapım ekleri köke gelip yeni anlamlı kelime türetir. Eklerle kelime hazinemiz büyür.", o:"süt + çü = sütçü, göz + lük = gözlük"}
 ],
 ipucu:"-e/-a: nereye gidiyorsun? -de/-da: nerede duruyorsun? -den/-dan: nereden geliyorsun? Üçünü sorduğunda ekleri bulursun.",
 kartlar:[["Çoğul eki hangisidir?","-lar / -ler"],["Kök ne demek?","Anlamlı, bölünemeyen kısım"],["Yönelme eki (nereye?)","-e / -a"],["Bulunma eki (nerede?)","-de / -da"],["Ayrılma eki (nereden?)","-den / -dan"],["'kuş' + çoğul eki","kuşlar"],["'ev' + çoğul eki","evler"],["Yapım eki ne yapar?","Yeni anlamlı kelime türetir"]],
 sorular:[
  {s:"Aşağıdakilerden hangisinde çoğul eki vardır?", c:["çocuklar","çocuk","okul","sınıf"], a:"Çocuklar sözcüğü -lar eki almıştır."},
  {s:"'Ali okula gitti.' cümlesinde 'okula' sözcüğündeki ek hangi soruya cevap verir?", c:["Nereye?","Nerede?","Nereden?","Neyi?"], a:"Okul-a eki, gidilen yönü gösterir; nereye?"},
  {s:"'Kedi evde uyuyor.' cümlesindeki 'evde' sözcüğündeki ek hangi soruya cevap verir?", c:["Nerede?","Nereye?","Nereden?","Kim?"], a:"-de eki bulunulan yeri gösterir."},
  {s:"'Bahçeden çiçek topladık.' cümlesinde 'bahçeden' sözcüğündeki ek hangisidir?", c:["-den","-e","-de","-ler"], a:"Bahçe-den ayrılma, uzaklaşma bildirir."},
  {s:"Aşağıdaki sözcüklerden hangisi doğru çoğul biçimidir?", c:["gözler","gözlar","gözlär","gözlarler"], a:"Göz sözcüğü ince ünlüyle bittiği için -ler alır."},
  {s:"'Sütçü' sözcüğünün kökü hangisidir?", c:["süt","sütçü","çü","ü"], a:"Süt anlamlı kısımdır; -çü ekidir."},
  {s:"'Kitaplar masada duruyor.' cümlesinde kaç sözcük ek almıştır?", c:["İkisi: kitaplar, masada","Yalnızca biri","Dördü","Üçü"], a:"Kitap-lar, masa-da ek almış sözcüklerdir."},
  {s:"Hangi sözcük ek almamış, yani köktür?", c:["deniz","denizler","denizde","denizden"], a:"Deniz köktür; diğerleri ek almıştır."},
  {s:"'Annem pazardan taze elma aldı.' cümlesinde 'pazardan' sözcüğü neyi anlatır?", c:["Elmanın alındığı yeri","Gidilen yönü","Bulunulan yeri","Alınan eşyayı"], a:"-dan eki ayrılma bildirir: pazardan alındı."},
  {s:"'Öğretmenin sınıfa girdiği anda çocuklar sustu.' cümlesindeki 'sınıfa' sözcüğüne hangi ek gelmiştir?", c:["Yönelme eki","Çoğul eki","Bulunma eki","Ayrılma eki"], a:"Sınıf-a, girilen yönü gösterir."}
 ]},
    {id:"tr3-yapim-ekleri", ad:"Yapım Ekleri ve Sözcük Türetme", e:"🌱",
     anlat:[
      {b:"Kök ve ek", m:"Sözcüğün anlamlı en küçük parçası köktür. Köke gelen ek yeni sözcük türetirse yapım eki olur.", o:"göz + lük = gözlük"},
      {b:"Sık kullanılan yapım ekleri", m:"-lık, -lı, -sız, -cı gibi ekler köke yeni anlam katar.", o:"tuz + lu = tuzlu; tuz + suz = tuzsuz"},
      {b:"Yapım eki ve çekim eki", m:"Çekim ekleri sözcüğü başka sözcüklerle ilişkilendirir. Yapım ekleri yeni sözcük yapar.", o:"kitap → kitaplar (çekim); kitap → kitapçı (yapım)"},
      {b:"Yeni sözcük, yeni tür", m:"Yapım ekiyle sözcüğün türü değişebilir.", o:"güzel → güzellik"}
     ],
     ipucu:"Yeni sözcük türetiyorsa yapım eki, ilişki kuruyorsa çekim eki!",
     kartlar:[["Sözcüğün anlamlı en küçük parçası","Kök"],["Yeni sözcük türeten ek","Yapım eki"],["tuz + lu","tuzlu"],["tuz + suz","tuzsuz"],["göz + lük","gözlük"],["kitap + çı","kitapçı"],["Çoğul eki hangi tür ektir?","Çekim eki"]],
     sorular:[
      {s:"Hangisi yapım ekiyle türemiş bir sözcüktür?", c:["tuzlu","evde","kitaplar"], a:"Tuzlu = tuz + lu."},
      {s:"'Gözlük' sözcüğünün kökü hangisidir?", c:["göz","lük","gözlük"], a:"Eki çıkarınca göz kalır."},
      {s:"Hangisi yapım ekidir?", c:["-cı","-ler","-de"], a:"-cı yeni sözcük türetir."},
      {s:"'Susuz' sözcüğündeki -suz eki ne anlam katar?", c:["Yokluk","Çokluk","Zaman"], a:"-suz yokluk anlamı verir."},
      {s:"'Kitapçı' sözcüğündeki -çı eki neyi bildirir?", c:["Meslek","Yer","Zaman"], a:"Kitap satan kişi, meslek bildirir."},
      {s:"'Sulu' sözcüğünün zıt anlamlısı hangisidir?", c:["susuz","sulama","sucu"], a:"-lı ve -sız zıt anlam kurar."},
      {s:"'Kitaplar' sözcüğündeki -lar eki hangi türdendir?", c:["Çekim eki","Yapım eki","Kök"], a:"Çoğul eki çekim ekidir."},
      {s:"'Güzel' sözcüğüne -lik eki gelince hangi sözcük oluşur?", c:["güzellik","güzeller","güzelde"], a:"Güzel + lik = güzellik."},
      {s:"'Balık' + '-çı' birleşince hangi sözcük olur?", c:["balıkçı","balıklar","balıkta"], a:"Balık + çı = balıkçı."},
      {s:"Hangi sözcük yapım eki almıştır?", c:["çiçekçi","çiçekler","çiçeğe"], a:"Çiçekçi = çiçek + çi."}
     ]}
  ]},
  {ad:"Cümle, Noktalama ve Yazım", konular:[
{id:"tr3-cumle-turleri", ad:"Cümle ve Cümle Türleri", e:"📝",
 anlat:[
  {b:"Cümle nedir?", m:"Duygu, düşünce ve isteklerimizi anlatan, anlamlı kelime dizisine cümle denir. Cümle büyük harfle başlar, noktalama işaretiyle biter.", o:"Ali bahçede top oynadı."},
  {b:"Olumlu ve olumsuz cümle", m:"Bir işin yapıldığını anlatan cümleler olumludur. Yapılmadığını anlatan cümleler olumsuzdur. Olumsuzlukta -ma/-me eki ya da değil sözcüğü kullanılır.", o:"Geldi. (olumlu) / Gelmedi. (olumsuz)"},
  {b:"Cümle türleri (anlamına göre)", m:"Bilgi veren cümle bildirme cümlesidir. Soru soran cümle soru cümlesidir. Heyecan, şaşkınlık anlatan cümle ünlem cümlesidir. İstek ve buyruk bildiren cümle emir cümlesidir.", o:"Yağmur yağıyor. Okula gittin mi? Ne güzel! Kapıyı kapat."},
  {b:"Cümlenin sonu", m:"Bildirme ve emir cümleleri genellikle nokta ile, soru cümleleri soru işaretiyle, ünlem cümleleri ünlem işaretiyle biter.", o:". ? !"}
 ],
 ipucu:"Nokta bilgi verir, soru işareti sorar, ünlem şaşırır, emir ise buyurur.",
 kartlar:[["Cümle nedir?","Anlamlı kelime dizisi"],["Cümle nasıl başlar?","Büyük harfle"],["Soru cümlesi sonu","Soru işareti (?)"],["Ünlem cümlesi sonu","Ünlem işareti (!)"],["Bildirme cümlesi sonu","Nokta (.)"],["'Gelmedi' olumlu mu?","Hayır, olumsuz"],["Olumsuzluk eki","-ma / -me"],["Emir cümlesi ne anlatır?","İstek, buyruk"]],
 sorular:[
  {s:"Aşağıdakilerden hangisi bir cümledir?", c:["Ayşe parka gitti.","Mavi masa","Bahçedeki çiçek","Uzun yol"], a:"Anlam tamamlayan, yargı bildiren dizi cümledir."},
  {s:"'Bugün hava çok güzel.' cümlesi hangi türdedir?", c:["Bildirme","Soru","Ünlem","Emir"], a:"Bilgi veriyor; bildirme cümlesidir."},
  {s:"'Okula erken geldin mi?' cümlesi hangi türdedir?", c:["Soru","Bildirme","Ünlem","Emir"], a:"Soru soruyor; sonu soru işaretiyle biter."},
  {s:"'Ne kadar güzel bir manzara!' cümlesi hangi türdedir?", c:["Ünlem","Soru","Emir","Bildirme"], a:"Hayranlık anlatıyor; ünlem cümlesidir."},
  {s:"'Defterini çantana koy.' cümlesi hangi türdedir?", c:["Emir","Soru","Ünlem","Olumsuz"], a:"Buyruk bildiriyor; emir cümlesidir."},
  {s:"Aşağıdakilerden hangisi olumsuz cümledir?", c:["Ödevimi yapmadım.","Ödevimi yaptım.","Ödevimi yapacağım.","Ödevimi yapıyorum."], a:"-ma eki olumsuzluk bildirir."},
  {s:"Hangi cümlenin sonuna soru işareti konur?", c:["Sen hangi dersi seviyorsun","Eve gittim","Ne güzel resim","Sessiz olun"], a:"Soru anlamı taşıyan cümle soru işaretiyle biter."},
  {s:"Hangisi doğru yazılmış cümledir?", c:["Çocuklar parkta oynuyor.","çocuklar parkta oynuyorlar","Çocuklar parkta oynuyo.","oynuyor çocuklar, parkta"], a:"Cümle büyük harfle başlar ve noktayla biter."},
  {s:"'Bugün sınıfta resim yapmadık.' cümlesi için hangisi doğrudur?", c:["Hem olumsuz hem bildirme cümlesidir.","Hem olumlu hem soru cümlesidir.","Hem olumsuz hem ünlem cümlesidir.","Hem olumlu hem emir cümlesidir."], a:"Yapmadık olumsuzdur ve bilgi verir."},
  {s:"Hangi cümle, hem olumlu hem de soru cümlesidir?", c:["Sen de bizimle gelecek misin?","Bizimle gelmedin mi?","Hiç gelmeyecek.","Haydi, gel!"], a:"Gelecek misin soru ve olumludur; gelmedin mi ise olumsuz sorudur."}
 ]},
{id:"tr3-noktalama", ad:"Noktalama İşaretleri", e:"❗",
 anlat:[
  {b:"Nokta ve virgül", m:"Nokta cümlenin sonuna konur. Virgül sıralı sözcükleri ayırır ve cümlede kısa duraklama yapar.", o:"Elma, armut, muz aldım."},
  {b:"Soru ve ünlem işareti", m:"Soru işareti soru anlamı taşıyan cümlelerin sonuna, ünlem işareti sevinç, şaşkınlık, korku gibi duyguları anlatan cümlelerin sonuna konur.", o:"Nereye gidiyorsun? Çok yaşa!"},
  {b:"İki nokta ve tırnak işareti", m:"İki nokta, açıklama ya da sıralama öncesinde kullanılır. Tırnak işareti ise birinin sözünü aynen aktarırken kullanılır.", o:"Annem şöyle dedi: \"Yarın erken kalk.\""},
  {b:"Kısa çizgi ve kesme işareti", m:"Satıra sığmayan sözcük kısa çizgiyle bölünür. Kesme işareti özel adlara gelen ekleri ayırır.", o:"Ankara'ya, Ali'nin"}
 ],
 ipucu:"Nokta bilgi, soru işareti soru, ünlem duygu; virgül ise 'nefes alma' işaretidir.",
 kartlar:[["Soru cümlesi sonuna","Soru işareti (?)"],["Duygu cümlesi sonuna","Ünlem işareti (!)"],["Sıralı sözcükleri ayırır","Virgül (,)"],["Özel ada gelen eki ayırır","Kesme işareti (')"],["Konuşmayı aynen aktarır","Tırnak işareti"],["Açıklamadan önce konur","İki nokta (:)"],["Cümlenin sonuna konur","Nokta (.)"],["Satıra sığmayan sözü bölen","Kısa çizgi (-)"]],
 sorular:[
  {s:"'Annem pazardan elma ... armut ... muz aldı.' cümlesinde boşluklara hangi işaret getirilmelidir?", c:["Virgül","Soru işareti","İki nokta","Ünlem"], a:"Sıralanan sözcükler virgülle ayrılır."},
  {s:"Hangi cümlenin sonuna ünlem işareti konmalıdır?", c:["Yaşasın, tatil başladı","Okula gittin","Bugün ne yaptın","Yarın gelecek"], a:"Sevinç anlatıyor; ünlem işareti getirilir."},
  {s:"'Öğretmen şöyle dedi ... \"Ödevlerinizi yarın getirin.\"' boşluğa hangisi gelir?", c:[":","?","!","."], a:"Açıklamadan ve alıntıdan önce iki nokta konur."},
  {s:"Hangisinde noktalama işareti doğru kullanılmıştır?", c:["Sen kimsin?","Sen kimsin.","Sen kimsin!","Sen kimsin,"], a:"Soru cümlesinin sonuna soru işareti konur."},
  {s:"'Ankara ... ya gideceğiz.' Boşluğa hangi işaret konur?", c:["'","!","?",":"], a:"Özel adlara gelen ekler kesme işaretiyle ayrılır: Ankara'ya."},
  {s:"Tırnak işareti ne için kullanılır?", c:["Birinin sözünü aynen aktarmak için","Soru sormak için","Cümleyi bitirmek için","Sıralama yapmak için"], a:"Tırnak, konuşmayı olduğu gibi yazmak için kullanılır."},
  {s:"'Kırmızı, sarı, yeşil ... boyaları aldım.' cümlesindeki virgül ne işe yarar?", c:["Sıralı sözcükleri ayırır.","Cümleyi bitirir.","Soru sorar.","Heyecan anlatır."], a:"Virgül, sıralanan sözcükleri birbirinden ayırır."},
  {s:"Hangi cümlede noktalama hatası vardır?", c:["Bugün kaç yaşına girdin.","Yaşasın! Tatil başladı.","Ne güzel bir gün!","Elma, armut, muz aldım."], a:"Soru cümlesinin sonuna nokta değil soru işareti konmalıdır."},
  {s:"'Alp, \"Beni de oyuna alır mısınız\" diye sordu.' cümlesinin doğru yazılışında tırnak içine ne eklenmelidir?", c:["Soru işareti","Nokta","Ünlem","Virgül"], a:"Tırnak içindeki cümle soru olduğu için sonuna soru işareti konur."},
  {s:"Hangisi 'Ali dedi ki: \"Yarın gelirim.\"' cümlesindeki işaretlerin doğru adlandırmasıdır?", c:["İki nokta, tırnak, nokta","Virgül, tırnak, ünlem","Nokta, kesme, soru","Soru, tırnak, virgül"], a:"Önce iki nokta, sonra tırnak içinde bir söz, sonda nokta vardır."}
 ]},
{id:"tr3-yazim-kurallari", ad:"Yazım Kuralları", e:"✍️",
 anlat:[
  {b:"Büyük harf kuralları", m:"Cümleler büyük harfle başlar. Kişi, yer, ülke, şehir, dağ, nehir ve kurum gibi özel adlar da büyük harfle başlar.", o:"Elif, İstanbul, Türkiye, Kızılay"},
  {b:"de / da yazımı", m:"Bağlaç olan de/da ayrı yazılır, 'dahi, bile' anlamı taşır. Bulunma hâli eki olan -de/-da ise kelimeye bitişik yazılır.", o:"Ben de geldim. / Evde kaldım."},
  {b:"ki yazımı", m:"Bağlaç olan ki ayrı yazılır. İlgi, aitlik bildiren -ki eki ise kelimeye bitişik yazılır.", o:"Biliyorum ki başaracaksın. / Evdeki oyuncak."},
  {b:"mi yazımı", m:"Soru eki 'mi' kendinden önceki sözcükten ayrı yazılır. Bunun dışında diğer eklerle birleşip öyle yazılır.", o:"Geldin mi? Okula gittiler mi?"}
 ],
 ipucu:"De/da: cümlede çıkarınca anlam bozulmuyorsa bağlaçtır, ayrı yaz. Ayrılıp yerini bulamıyorsa ek, bitişik!",
 kartlar:[["Özel adlar nasıl başlar?","Büyük harfle başlar"],["'Ben de gittim' de/da","Ayrı yazılır (bağlaç)"],["'Evde kaldı' de/da","Bitişik yazılır (ek)"],["Soru eki mi nasıl yazılır?","Önceki sözcükten ayrı"],["Bağlaç ki nasıl yazılır?","Ayrı yazılır, cümleleri bağlar"],["'Evdeki' ki","Bitişik yazılır, ilgi eki"],["Cümle başı büyük mü küçük mü?","Büyük harf"],["Şehir adları nasıl yazılır?","Baş harfi büyük"]],
 sorular:[
  {s:"Hangi sözcük her zaman büyük harfle başlar?", c:["Ankara","şehir","okul","kalem"], a:"Ankara özel addır; özel adlar büyük harfle başlar."},
  {s:"Hangi cümlede 'de' doğru yazılmıştır?", c:["Ben de geleceğim.","Bende geleceğim.","Ben-de geleceğim.","Benda geleceğim."], a:"Dahi anlamındaki de ayrı yazılır."},
  {s:"'Sınıf... çok kalabalıktı.' boşluğa hangi yazım uygundur?", c:["Sınıfta","Sınıf ta","Sınıf da","Sınıf te"], a:"Bulunma hâli eki olduğu için bitişik yazılır: sınıfta."},
  {s:"'Okula geldin ... ?' boşluğa nasıl yazılır?", c:["mi","mı","mu","mü"], a:"Soru eki, kendinden önceki ünlüye uyar; geldin mi? ince-düz ünlüdür."},
  {s:"Hangi cümle doğru yazılmıştır?", c:["Annem de babam da geldi.","Annemde babamda geldi.","Annem de babamda geldi.","Annemde babam da geldi."], a:"Bağlaç olan de iki yerde de ayrı yazılmıştır."},
  {s:"'Bahçe... çiçekler çok güzel.' Boşluğa hangi yazım gelir?", c:["deki","de ki","da ki","dı ki"], a:"İlgi eki -ki bitişik yazılır: bahçedeki."},
  {s:"Hangisinde yazım yanlışı vardır?", c:["istanbul çok büyük bir şehirdir.","Eylül ayında okula başladım.","Ayşe parka gitti.","Türkiye'nin başkenti Ankara'dır."], a:"Cümle başı ve özel ad olan İstanbul büyük harfle başlamalıdır."},
  {s:"'Biliyorum ki bu işi başaracaksın.' cümlesindeki 'ki' ile ilgili hangisi doğrudur?", c:["Bağlaçtır, ayrı yazılır.","Ektir, bitişik yazılır.","Soru ekidir.","Çoğul ekidir."], a:"Bu ki iki cümleyi bağlar ve ayrı yazılır."},
  {s:"Hangi cümlede 'mi' yanlış yazılmıştır?", c:["Gelmişmi acaba?","Gelmiş mi acaba?","Okula gitti mi?","Sen ağladın mı?"], a:"Soru eki mi ayrı yazılır."},
  {s:"'Sen ... bizimle gel, çünkü bahçe ... çiçekler açtı.' Boşlukları sırasıyla doğru yazım hangisidir?", c:["de, deki","da, ki","de, ki","da, de ki"], a:"Sen de: bağlaç, ayrı; bahçedeki: ilgi eki, bitişik."}
 ]},
    {id:"tr3-kisaltma-sayi", ad:"Kısaltmalar ve Sayıların Yazımı", e:"🔠",
     anlat:[
      {b:"Kısaltma", m:"Uzun sözcük ya da söz öbeklerinin kısa yazılışına kısaltma denir. Kurum kısaltmaları büyük harfle yazılır.", o:"TBMM, TDK, TRT"},
      {b:"Noktalı kısaltmalar", m:"Bazı kısaltmaların sonuna nokta konur.", o:"Dr., Prof., vb., Cad., Sok."},
      {b:"Ölçü birimleri", m:"Ölçü birimlerinin kısaltmalarında nokta kullanılmaz. Küçük harfle yazılırlar.", o:"kg, cm, km, m"},
      {b:"Sayıların yazımı", m:"Yazıyla yazılan sayılar ayrı yazılır. Rakamlara gelen ekler kesme işaretiyle ayrılır.", o:"yüz yirmi üç; 1923'te"}
     ],
     ipucu:"Kurum kısaltması büyük harf, ölçü birimi küçük harf: kg, cm, km!",
     kartlar:[["TBMM açılımı","Türkiye Büyük Millet Meclisi"],["TDK açılımı","Türk Dil Kurumu"],["kg neyin kısaltmasıdır?","kilogram"],["cm neyin kısaltmasıdır?","santimetre"],["vb. açılımı","ve benzeri"],["Dr. açılımı","Doktor"],["Yazıyla sayılar nasıl yazılır?","Ayrı yazılır"]],
     sorular:[
      {s:"'TBMM' kısaltmasının açılımı nedir?", c:["Türkiye Büyük Millet Meclisi","Türk Büyük Milli Meclis","Türkiye Bilim Merkezi"], a:"TBMM: Türkiye Büyük Millet Meclisi."},
      {s:"'kg' neyin kısaltmasıdır?", c:["Kilogram","Kilometre","Kutu"], a:"kg kilogramdır."},
      {s:"Hangisi santimetrenin doğru kısaltmasıdır?", c:["cm","Cm.","Sm"], a:"Ölçü birimleri küçük harfle ve noktasız yazılır."},
      {s:"'vb.' kısaltması ne demektir?", c:["ve benzeri","ve başkası","veya bazen"], a:"vb.: ve benzeri."},
      {s:"Hangi sayı doğru yazılmıştır?", c:["yüz yirmi üç","yüzyirmiüç","yüz yirmiüç"], a:"Yazıyla sayılar ayrı yazılır."},
      {s:"Hangisi doğru yazılmıştır?", c:["1923'te","1923te","1923 'te"], a:"Rakamdan sonra gelen ek kesme ile ayrılır."},
      {s:"'Dr.' kısaltması hangi unvan içindir?", c:["Doktor","Dedektif","Direktör"], a:"Dr. doktorun kısaltmasıdır."},
      {s:"Hangisi bir kurum kısaltmasıdır?", c:["TRT","kg","vb."], a:"TRT bir kurum adı kısaltmasıdır."},
      {s:"'Sok.' kısaltması neyi gösterir?", c:["Sokak","Soğuk","Sonuç"], a:"Adreslerde Sok. sokaktır."},
      {s:"Hangi tarih doğru yazılmıştır?", c:["23 Nisan 1920","23 Nisan1920","23Nisan 1920"], a:"Gün, ay ve yıl aralarında boşlukla yazılır."}
     ]}
  ]},
  {ad:"Okuma ve Anlama", konular:[
{id:"tr3-okuma-anlama", ad:"Okuduğunu Anlama", e:"📖",
 anlat:[
  {b:"Konu nedir?", m:"Metnin kim ya da ne hakkında olduğuna metnin konusu denir. Metin hakkında 'Bu metin neyi anlatıyor?' diye sorarak konuyu buluruz.", o:"Metin ağaçların faydalarını anlatıyorsa konu: ağaçlar."},
  {b:"Ana fikir ve başlık", m:"Yazarın okuyucuya vermek istediği öğüt ya da mesaja ana fikir denir. Başlık ise metnin konusunu ya da içeriğini en iyi özetleyen kısa addır.", o:"Ana fikir: Çalışkan olmak başarı getirir."},
  {b:"5N1K soruları", m:"Bir olayı tam anlamak için Ne? Nerede? Ne zaman? Kim? Neden? Nasıl? sorularını sorarız. Bunlar metindeki bilgiyi bulmamıza yardım eder.", o:"Ali dün parkta top oynadı. (Kim: Ali, Ne zaman: dün, Nerede: parkta)"},
  {b:"Çıkarım yapmak", m:"Bazı bilgiler metinde açıkça yazmaz. Cümlelerden ipucu bularak doğru sonuca ulaşmaya çıkarım yapmak denir.", o:"Şemsiyesi ıslak: yağmur yağmış olabilir."}
 ],
 ipucu:"Konu: 'Ne anlatıyor?' Ana fikir: 'Bize ne öğretiyor?' 5N1K: metni sorgulayan altı dedektif sorusu!",
 kartlar:[["Metnin konusu nedir?","Metnin neyi anlattığı"],["Ana fikir nedir?","Yazarın vermek istediği mesaj"],["Başlık ne işe yarar?","Metni kısaca özetler"],["5N1K açılımı","Ne, nerede, ne zaman, kim, neden, nasıl"],["Çıkarım nedir?","İpuçlarıyla sonuç bulma"],["'Kim?' neyi sorar?","Olayın kişisini"],["'Neden?' neyi sorar?","Olayın sebebini"],["'Nerede?' neyi sorar?","Olayın yerini"]],
 sorular:[
  {s:"Metin: Hasan her sabah erken kalkar, dişlerini fırçalar ve kahvaltı eder. Okula zamanında gider. Bu metnin konusu aşağıdakilerden hangisidir?", c:["Hasan'ın sabah rutini","Hasan'ın okulu","Dişlerin önemi","Kahvaltı yemekleri"], a:"Metin Hasan'ın sabah yaptıklarını anlatıyor."},
  {s:"Metin: Dün parkta Elif'le Can salıncakta sallandılar. Sonra bir ağacın altında kitap okudular. 'Elif ile Can dün nerede oynadı?' sorusunun cevabı nedir?", c:["Parkta","Okulda","Bahçede","Evde"], a:"Metinde olayın yeri parktır."},
  {s:"Metin: Arı çok çalışkandır. Her gün çiçeklerden nektar toplar ve bal yapar. Bu metne en uygun başlık hangisidir?", c:["Çalışkan Arı","Çiçekler","Tatlı Bal","Yaz Mevsimi"], a:"Metnin merkezinde arının çalışkanlığı vardır."},
  {s:"Metin: Su kıttır. Musluğu açık bırakmak suyu boşa harcar. Bu metnin ana fikri hangisidir?", c:["Su tasarruflu kullanılmalıdır.","Musluk açılmalıdır.","Su soğuk olur.","Su içmek sağlıklıdır."], a:"Yazar bize suyu boşa harcamamamız gerektiğini söylüyor."},
  {s:"Metin: Ayşe sabah uyandı, penceresini açtı ve her yerin beyaza büründüğünü gördü. Ayşe'nin gördüğü şey büyük olasılıkla nedir?", c:["Kar","Yağmur","Güneş","Sis"], a:"Her yerin beyaza bürünmesi karın yağdığını gösterir."},
  {s:"Metin: Tarık dün okula geç kaldı çünkü servis arızalandı. 'Tarık neden okula geç kaldı?' sorusunun cevabı nedir?", c:["Servis arızalandı.","Uyuyakaldı.","Hasta oldu.","Yağmur yağdı."], a:"Neden sorusunun cevabı çünkü sözcüğünden sonra gelir."},
  {s:"Metin: Mert, dün akşam evde annesine yemek hazırlamada yardım etti. 'Mert ne yaptı?' sorusu hangi 5N1K sorusudur?", c:["Ne?","Kim?","Nerede?","Ne zaman?"], a:"Yapılan işi sorar; 'ne' sorusudur."},
  {s:"Metin: Kaplumbağa yavaş yürür ama hiç durmaz. Sonunda yarışı kazanır. Bu hikâyenin ana fikri hangisidir?", c:["Azimle çalışan başarır.","Hızlı yürümek iyidir.","Yarışlar eğlencelidir.","Kaplumbağalar yavaştır."], a:"Hiç durmadan yürüyen kaplumbağa kazanıyor; mesaj azimdir."},
  {s:"Metin: Defne sınıfta yeni bir arkadaşı olduğunu fark etti. Yanına gidip kendini tanıttı ve onunla oyun oynamayı önerdi. Bu parçadan Defne için hangisi çıkarılır?", c:["Arkadaş canlısıdır.","Utangaçtır.","Tembeldir.","Kıskançtır."], a:"Yeni arkadaşa yaklaşıp oyun önermesi arkadaş canlısı olduğunu gösterir."},
  {s:"Metin: Zeynep güzel bir resim yaptı. Resmi duvara astı. Annesi resmi çok beğendi. Aşağıdakilerden hangisi metinde yoktur?", c:["Resmin adı","Resmi yapan kişi","Resmin asıldığı yer","Annenin tepkisi"], a:"Resmin adı metinde verilmemiştir."}
 ]},
    {id:"tr3-okuma-stratejileri", ad:"Okuma Stratejileri: Tahmin ve Özet", e:"🔍",
     anlat:[
      {b:"Okumadan önce", m:"Başlığa ve resimlere bakarak metnin konusunu tahmin ederiz. Okuduktan sonra tahminimizi kontrol ederiz."},
      {b:"Anahtar sözcük", m:"Metni anlamak için önemli sözcükleri belirleriz. Bu sözcükler konuyu anlatır."},
      {b:"Çıkarım", m:"Yazar her şeyi açıkça yazmayabilir. İpuçlarından yola çıkarak sonucu buluruz.", o:"Yerler ıslak, şemsiyeler açık. → Yağmur yağmış."},
      {b:"Özetleme", m:"Özet, metnin önemli bilgilerini kısa ve kendi sözlerimizle yazmaktır. Gereksiz ayrıntıları atarız."}
     ],
     ipucu:"Tahmin et, anahtar sözcüğü bul, ipucundan çıkarım yap, kısaca özetle!",
     kartlar:[["Okumadan önce ne yaparız?","Başlıktan tahmin ederiz"],["Anahtar sözcük nedir?","Konuyu anlatan önemli sözcük"],["Çıkarım nedir?","İpucundan sonuç bulmak"],["Özet nedir?","Metnin kısa anlatımı"],["Özette neleri atarız?","Gereksiz ayrıntıları"],["Tahmini ne zaman kontrol ederiz?","Okuduktan sonra"]],
     sorular:[
      {s:"Başlığa bakarak metnin konusunu düşünmeye ne denir?", c:["Tahmin","Özet","Dinleme"], a:"Bu strateji tahmindir."},
      {s:"Metindeki önemli bilgileri kısa ve kendi sözlerimizle yazmaya ne denir?", c:["Özetleme","Boyama","Kopyalama"], a:"Buna özetleme denir."},
      {s:"Yerler ıslak, insanlar şemsiye taşıyor. Ne olmuş olabilir?", c:["Yağmur yağmış","Güneş çıkmış","Rüzgâr esmemiş"], a:"İpuçları yağmuru gösterir."},
      {s:"Özetlerken neyi atarız?", c:["Gereksiz ayrıntıları","Ana düşünceyi","Metnin konusunu"], a:"Özette yalnızca önemli bilgiler kalır."},
      {s:"Anahtar sözcükler neyi gösterir?", c:["Metnin konusunu","Sayfa sayısını","Yazarın yaşını"], a:"Anahtar sözcükler konuyu anlatır."},
      {s:"Elif tahminini okuduktan sonra ne yapmalıdır?", c:["Metinle karşılaştırmalı","Tahmini unutmalı","Metni yırtmalı"], a:"Tahmin metinle kontrol edilir."},
      {s:"Ali'nin yüzü kızarmıştı, elleri titriyordu. Ali nasıl hissediyor olabilir?", c:["Heyecanlı ya da utangaç","Uykulu","Aç"], a:"Kızarma ve titreme heyecan ya da utanç ipucudur."},
      {s:"Hangisi iyi bir özetin özelliğidir?", c:["Kısa ve öz olması","Metinden uzun olması","Konudan sapması"], a:"Özet kısa olur."},
      {s:"Çıkarım yaparken neye dayanırız?", c:["Metindeki ipuçlarına","Rastgele düşünceye","Hiçbir şeye"], a:"İpuçlarından sonuç çıkarılır."},
      {s:"Metni okumadan önce hangisini yapmak yararlıdır?", c:["Başlığa ve görsellere bakmak","Metni silmek","Son cümleyi atlamak"], a:"Başlık ve görseller konuyu tahmin ettirir."}
     ]},
{id:"tr3-hikaye-sebep-sonuc", ad:"Hikâye, Sebep-Sonuç, Karşılaştırma", e:"📚",
 anlat:[
  {b:"Hikâye unsurları", m:"Bir hikâyede kişi (kahraman), yer, zaman ve olay bulunur. Olay başlangıç, gelişme ve sonuç bölümlerinden oluşur.", o:"Kişi: Ayşe. Yer: orman. Zaman: bir sabah. Olay: kaybolan kedi."},
  {b:"Sebep-sonuç", m:"Bir olayın nedeni sebeptir, o nedenden doğan durum sonuçtur. 'Çünkü, için, bu yüzden' gibi sözcükler ilişkiyi kurar.", o:"Yağmur yağdı, bu yüzden ıslandık."},
  {b:"Sebebi nasıl buluruz?", m:"'Neden?' diye sorarsak sebebi buluruz. 'Ne oldu?' diye sorarsak sonucu buluruz.", o:"Ders çalıştığı için sınavı iyi geçti. (Sebep: ders çalışması)"},
  {b:"Karşılaştırma", m:"İki varlığın benzerlik ve farklarını söylemek karşılaştırmadır. 'daha, en, gibi, kadar' sözcükleri karşılaştırmada kullanılır.", o:"Kedi köpekten daha küçüktür."}
 ],
 ipucu:"Hikâye = Kim, nerede, ne zaman, ne oldu? Sebep: 'Neden?' Sonuç: 'Ne oldu?'",
 kartlar:[["Hikâyenin dört unsuru","Kişi, yer, zaman, olay"],["Sebep ne demek?","Olayın nedeni"],["Sonuç ne demek?","Nedenin doğurduğu durum"],["'Çünkü' sebep mi sonuç mu bildirir?","Sebep"],["Karşılaştırma sözcüğü","daha"],["Olay hangi bölümlerden oluşur?","Başlangıç, gelişme, sonuç"],["'Bu yüzden' sonuç bildirir mi?","Evet, sonucu"],["En ne anlamı katar?","Üstünlük"]],
 sorular:[
  {s:"Aşağıdakilerden hangisi hikâyenin unsurlarından biri değildir?", c:["Resim","Kişi","Yer","Zaman"], a:"Hikâyenin unsurları kişi, yer, zaman ve olaydır."},
  {s:"'Yağmur yağdığı için maç iptal edildi.' cümlesinde sebep hangisidir?", c:["Yağmur yağması","Maçın iptali","Spor yapmak","Oyuncular"], a:"Maçın iptal edilme nedeni yağmurdur."},
  {s:"'Ali hasta olduğu için okula gelemedi.' cümlesinde sonuç hangisidir?", c:["Okula gelememesi","Ali'nin hasta olması","Öğretmen","Arkadaşları"], a:"Hasta olmanın sonucu, okula gelememektir."},
  {s:"'Kar yağdı, bu yüzden yollar kapandı.' cümlesindeki sebep-sonuç ilişkisi için hangisi doğrudur?", c:["Sebep kar yağması, sonuç yolların kapanmasıdır.","Sebep yolların kapanması, sonuç kar yağmasıdır.","Sebep ve sonuç aynıdır.","Cümlede sebep yoktur."], a:"Önce kar yağdı (sebep), sonra yollar kapandı (sonuç)."},
  {s:"'Bu hikâyede bir sabah, Mert ormanda kaybolmuş bir kuş yavrusu buldu.' cümlesinde zaman bildiren ifade hangisidir?", c:["bir sabah","ormanda","kuş yavrusu","Mert"], a:"Zamanı bir sabah ifadesi bildirir."},
  {s:"Hangisinde karşılaştırma vardır?", c:["Elif, Ayşe'den daha uzundur.","Elif sınıfa geldi.","Ayşe kitap okuyor.","Elif bahçede oynadı."], a:"'daha' sözcüğü iki kişiyi karşılaştırır."},
  {s:"'Çünkü ders çalışmadı, bu yüzden notu düşük geldi.' ifadesinde sebep hangisidir?", c:["Ders çalışmaması","Notun düşük olması","Okula gitmesi","Sınav olması"], a:"Düşük notun nedeni ders çalışmamaktır."},
  {s:"'Fil, fareden çok daha büyüktür.' cümlesinde hangi iki varlık karşılaştırılmıştır?", c:["Fil ve fare","Fil ve kedi","Fare ve kedi","Fil ve aslan"], a:"Cümlede fil ve fare karşılaştırılıyor."},
  {s:"Hangi cümle sebep bildirmektedir?", c:["Kapı açıldı, çünkü rüzgâr esiyordu.","Kapı açıldı.","Kapıyı kapattım.","Kapıdan çıktım."], a:"Çünkü sözcüğü sebep bildirir."},
  {s:"'Kedi çok acıkmıştı, bu yüzden mutfağa girip yemek aradı.' cümlesinde sebep hangisidir?", c:["Kedinin acıkması","Mutfağa girmesi","Yemek araması","Mutfağın kapısı"], a:"Bu yüzden sözcüğünden önceki bölüm sebebi, sonraki bölüm sonucu bildirir."}
 ]},
    {id:"tr3-metin-turleri", ad:"Metin Türleri", e:"📰",
     anlat:[
      {b:"Hikâye", m:"Hikâye (öykü), kişi, yer, zaman ve olay unsurlarıyla anlatılan metindir. Gerçek ya da hayalî olabilir."},
      {b:"Masal ve fabl", m:"Masallar hayalî olaylar anlatır; 'Bir varmış, bir yokmuş' diye başlar. Fabllarda hayvanlar insan gibi konuşur ve bir ders verilir."},
      {b:"Şiir ve bilgilendirici metin", m:"Şiir dizelerle yazılır. Bilgilendirici metin gerçek bilgiler verir, olayları hayal ürünü değildir."},
      {b:"Haber ve mektup", m:"Haber metni güncel bir olayı kim, ne, nerede, ne zaman sorularına cevap vererek anlatır. Mektup ise birine yazılır."}
     ],
     ipucu:"Hikâye olay anlatır, masal hayalîdir, fabl ders verir, şiir dizelerle yazılır!",
     kartlar:[["Hikâye nedir?","Olay anlatan metin"],["Masal nasıl başlar?","Bir varmış, bir yokmuş"],["Fabllarda kimler konuşur?","Hayvanlar"],["Fabl ne verir?","Ders"],["Şiir hangi birimlerle yazılır?","Dizelerle"],["Bilgi veren metin","Bilgilendirici metin"]],
     sorular:[
      {s:"'Bir varmış, bir yokmuş...' sözleriyle başlayan metin türü hangisidir?", c:["Masal","Haber","Şiir"], a:"Masallar bu sözle başlar."},
      {s:"Hayvanların insan gibi konuşup ders verdiği metin türü hangisidir?", c:["Fabl","Haber","Mektup"], a:"Fabllarda hayvanlar konuşur ve ders verilir."},
      {s:"Dizelerle yazılan metin hangisidir?", c:["Şiir","Hikâye","Bilgilendirici metin"], a:"Şiir dizelerden oluşur."},
      {s:"Kişi, yer, zaman ve olay unsurlarını içeren metin türü hangisidir?", c:["Hikâye","Şiir","Tarif"], a:"Hikâyenin unsurları bunlardır."},
      {s:"Hangisi bilgilendirici metindir?", c:["Bitkilerin nasıl büyüdüğünü anlatan yazı","Aslan ile tavşanın konuştuğu öykü","Sevgiyi anlatan dörtlük"], a:"Gerçek bilgi veren yazı bilgilendiricidir."},
      {s:"Haber metni hangi soruların cevabını verir?", c:["Ne oldu, kim, nerede, ne zaman?","Kaç kilo?","Hangi renk?"], a:"Haber olayı kim, ne, nerede, ne zaman sorularıyla anlatır."},
      {s:"Masalların genel özelliği nedir?", c:["Hayalî olaylar anlatır","Yalnızca gerçek olayları anlatır","Yalnızca sayılardan oluşur"], a:"Masallar hayal ürünüdür."},
      {s:"Fabl okuyan Elif ne elde eder?", c:["Bir ders çıkarır","Matematik kuralı","Şarkı sözü"], a:"Fabllarda öğüt/ders vardır."},
      {s:"Birine duygularını anlatmak için yazılan metin hangisidir?", c:["Mektup","Fabl","Haber"], a:"Mektup birine yazılır."},
      {s:"Gazetede yer alan, güncel olayı anlatan yazı hangisidir?", c:["Haber","Masal","Şiir"], a:"Güncel olayı haber anlatır."}
     ]},
    {id:"tr3-tablo-gorsel", ad:"Tablo ve Liste Okuma", e:"📊",
     anlat:[
      {b:"Tablo nedir?", m:"Tablo, bilgileri satır ve sütunlarla düzenli gösterir. Satır yatay, sütun dikey sıradır."},
      {b:"Tablodan bilgi bulma", m:"Önce tablonun başlığına bakarız. Sonra ilgili satır ve sütunun kesiştiği yeri okuruz.", o:"Elif satırı ile kitap sütunu"},
      {b:"Karşılaştırma", m:"Tablodaki sayıları karşılaştırarak en çok, en az, toplam ve farkı buluruz."},
      {b:"Liste", m:"Liste, bilgileri alt alta sıralar. Alışveriş listesi buna örnektir."}
     ],
     ipucu:"Başlığa bak, satır ve sütunu bul, sayıları karşılaştır!",
     kartlar:[["Yatay sıraya ne denir?","Satır"],["Dikey sıraya ne denir?","Sütun"],["Tabloda önce neye bakılır?","Başlığa"],["En çok olan nasıl bulunur?","En büyük sayıya bakılır"],["Fark nasıl bulunur?","Çıkarma ile"],["Liste nedir?","Alt alta sıralı bilgi"]],
     sorular:[
      {s:"Tabloda yatay sıralara ne denir?", c:["Satır","Sütun","Başlık"], a:"Yatay sıra satırdır."},
      {s:"Tabloda dikey sıralara ne denir?", c:["Sütun","Satır","Not"], a:"Dikey sıra sütundur."},
      {s:"Okunan kitaplar: Ali 5, Elif 8, Mert 3, Zeynep 6. En çok kitabı kim okumuştur?", c:["Elif","Ali","Mert"], a:"8 en büyük sayıdır."},
      {s:"Okunan kitaplar: Ali 5, Elif 8, Mert 3, Zeynep 6. En az kitabı kim okumuştur?", c:["Mert","Ali","Zeynep"], a:"3 en küçük sayıdır."},
      {s:"Okunan kitaplar: Ali 5, Elif 8, Mert 3, Zeynep 6. Ali ile Zeynep toplam kaç kitap okumuştur?", c:["11","9","13"], a:"5 + 6 = 11."},
      {s:"Okunan kitaplar: Ali 5, Elif 8, Mert 3, Zeynep 6. Elif, Mert'ten kaç kitap fazla okumuştur?", c:["5","3","11"], a:"8 - 3 = 5."},
      {s:"Ders sayısı: Pazartesi 3, Salı 4, Çarşamba 5. Hangi gün en çok ders vardır?", c:["Çarşamba","Salı","Pazartesi"], a:"5 en büyük sayıdır."},
      {s:"Ders sayısı: Pazartesi 3, Salı 4, Çarşamba 5. Üç günde toplam kaç ders vardır?", c:["12","11","13"], a:"3 + 4 + 5 = 12."},
      {s:"Tablodan bilgi bulmak için önce neye bakarız?", c:["Başlığa","Rengine","Kenarına"], a:"Başlık tablonun konusunu söyler."},
      {s:"Alt alta sıralanmış bilgiye ne denir?", c:["Liste","Dörtlük","Mektup"], a:"Alt alta sıralı bilgi listedir."}
     ]}
  ]},
  {ad:"Yazılı Anlatım", konular:[
    {id:"tr3-yazili-anlatim", ad:"Yazılı Anlatım: Günlük, Anı, Duyuru", e:"📝",
     anlat:[
      {b:"Günlük", m:"Günlük, yaşadığımız olayları tarih atarak yazdığımız kişisel yazıdır.", o:"12 Mart. Bugün okulda resim yaptık."},
      {b:"Anı", m:"Anı, geçmişte yaşanmış ve unutulmayan bir olayın anlatılmasıdır. Genellikle 'ben' diliyle yazılır."},
      {b:"Duyuru", m:"Duyuru, herkese bilgi vermek için yazılır. Ne, ne zaman ve nerede sorularının cevabı bulunur.", o:"Gezi cuma günü saat 09.00'da başlayacaktır."},
      {b:"Düzenli yazma", m:"Yazarken giriş, gelişme ve sonuç bölümleri oluştururuz. Cümleleri bağlantılı kurar, yazım ve noktalama kurallarına uyarız."}
     ],
     ipucu:"Günlük tarihli, anı geçmişten, duyuru herkese; giriş-gelişme-sonuç unutma!",
     kartlar:[["Günlük nasıl yazılır?","Tarih atılarak"],["Anı neyi anlatır?","Geçmişte yaşananı"],["Duyuru kimler için yazılır?","Herkes için"],["Duyuruda hangi bilgiler olur?","Ne, ne zaman, nerede"],["Yazının bölümleri","Giriş, gelişme, sonuç"],["Anı hangi kişiyle yazılır?","Genellikle 'ben'"]],
     sorular:[
      {s:"Yaşadıklarımızı tarih atarak yazdığımız yazı hangisidir?", c:["Günlük","Duyuru","Fabl"], a:"Günlük tarihle yazılır."},
      {s:"Geçmişte yaşanan unutulmaz bir olayın anlatılmasına ne denir?", c:["Anı","Duyuru","Tarif"], a:"Bu yazıya anı denir."},
      {s:"Herkese bilgi vermek için yazılan yazı hangisidir?", c:["Duyuru","Anı","Günlük"], a:"Duyuru herkese bilgi verir."},
      {s:"Duyuruda hangisi bulunmalıdır?", c:["Etkinliğin yeri ve zamanı","Gizli düşünceler","Hikâye kahramanı"], a:"Yer ve zaman bilgisi gerekir."},
      {s:"Hangi cümle günlüğe uygundur?", c:["Bugün okulda çok güzel bir gün geçirdim.","Hepinizi toplantıya bekliyoruz.","Bir varmış, bir yokmuş."], a:"Günlükte kişisel yaşantı anlatılır."},
      {s:"Yazının bölümleri hangi sıradadır?", c:["Giriş, gelişme, sonuç","Sonuç, giriş, gelişme","Gelişme, sonuç, giriş"], a:"Yazı bu sırayla ilerler."},
      {s:"'Yarın saat 10.00'da kütüphane gezisi var.' hangi türdür?", c:["Duyuru","Anı","Masal"], a:"Bilgi veren bu yazı duyurudur."},
      {s:"Anı yazarken genellikle hangi anlatım kullanılır?", c:["'Ben' diye anlatmak","Hiç olay anlatmamak","Yalnızca sayı yazmak"], a:"Anı kişinin kendi yaşantısıdır."},
      {s:"Günlüğe ilk olarak ne yazarız?", c:["Tarihi","Sonucu","Adresi"], a:"Günlük tarihle başlar."},
      {s:"Yazarken yazım ve noktalama kurallarına neden uyarız?", c:["Okuyanın kolay anlaması için","Yazı uzasın diye","Kalem bitsin diye"], a:"Doğru yazım anlamı netleştirir."}
     ]}
  ]}
]});
